import { describe, expect, it } from "@jest/globals";
import { MAX_SLUG_LENGTH, PostSlug } from "./blog-post-slug";

describe("PostSlug", () => {
	it("MAX_SLUG_LENGTH is 96", () => {
		expect(MAX_SLUG_LENGTH).toBe(96);
	});

	it("safeParse returns success", () => {
		expect(PostSlug.safeParse("hello").success).toBe(true);
		expect(PostSlug.safeParse("my-post-title").success).toBe(true);
		expect(PostSlug.safeParse("post-2024-recap").success).toBe(true);
	});

	it("regex", () => {
		expect(PostSlug.safeParse("Hello").success).toBe(false);
		expect(PostSlug.safeParse("he--llo").success).toBe(false);
	});

	it("rejects an empty slug", () => {
		expect(PostSlug.safeParse("").success).toBe(false);
	});

	it("max", () => {
		const tooLong = "a".repeat(MAX_SLUG_LENGTH + 1);

		expect(PostSlug.safeParse(tooLong).success).toBe(false);
	});
});

import { z } from "zod";

/** Upper bound on a post slug's length, enforced by the schema below. */
export const MAX_SLUG_LENGTH = 96;

/**
 * Shape of a post slug: lowercase alphanumeric groups joined by single
 * hyphens, with no leading, trailing, or doubled hyphen. A slug becomes part
 * of a URL path and a cache key, so it is validated before either is built
 * from it rather than trusted as-is.
 */
export const PostSlug = z
	.string()
	.min(1)
	.max(MAX_SLUG_LENGTH)
	.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);

export type PostSlug = z.infer<typeof PostSlug>;

/** Message shown next to a slug field that failed {@link PostSlug}. */
export const SLUG_VALIDATION_MESSAGE =
	"Use lowercase letters, numbers, and single hyphens (e.g. my-post-title).";

